// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivateBank, Log} from "../src/PrivateBank.sol";

contract InvMutTest is Test {
    PrivateBank c;
    function setUp() public { c = new PrivateBank(address(new Log())); }

    function testFuzz_property(uint256 amount, uint256 withdraw, address actor) public {
        uint256 amt = bound(amount, 1 ether, 1000 ether);
        vm.assume(actor != address(c));
        vm.assume(actor.code.length == 0);

        vm.deal(actor, amt);
        vm.prank(actor);
        c.Deposit{value: amt}();

        uint256 before = c.balances(actor);
        uint256 w = bound(withdraw, 1, amt);

        vm.prank(actor);
        c.CashOut(w);

        assertTrue(c.balances(actor) == before - w);
    }
}
